import pandas as pd
import numpy as np

# Test 1: Series.mean() with float16 overflow
try:
    result = pd.Series([60000.0, 60000.0], dtype='float16').mean()
    probe("Series([60000.0, 60000.0], dtype='float16').mean()", result)
except Exception as e:
    probe("Series([60000.0, 60000.0], dtype='float16').mean()", "__error__: " + type(e).__name__ + ": " + str(e))

